<script setup lang="ts">
import { MapPin, ArrowUpRight, Sparkles } from 'lucide-vue-next'
import { attributeLabels, priceLabel, type Recommendation } from '../../shared/domain'
const props=defineProps<{restaurant:Recommendation}>();const emit=defineEmits<{swipe:[direction:'like'|'skip'];detail:[]}>();const start=ref<{x:number;y:number}|null>(null);const offset=ref(0)
function end(e:PointerEvent){if(!start.value)return;const dx=e.clientX-start.value.x,dy=e.clientY-start.value.y;if(Math.abs(dx)>85&&Math.abs(dx)>Math.abs(dy)*1.3)emit('swipe',dx>0?'like':'skip');else if(Math.abs(dx)<8&&Math.abs(dy)<8)emit('detail');start.value=null;offset.value=0}
</script>
<template><article class="restaurant-card" :style="{transform:`translateX(${offset}px) rotate(${offset/30}deg)`}" @pointerdown="e=>{start={x:e.clientX,y:e.clientY}}" @pointermove="e=>{if(start)offset=Math.max(-130,Math.min(130,e.clientX-start.x))}" @pointerup="end" @pointercancel="start=null;offset=0" @pointerleave="start=null;offset=0"><img :src="restaurant.coverImageUrl" :alt="`${restaurant.name}の料理${restaurant.demo?'のイメージ':''}`" draggable="false"><div class="card-gradient"/><span class="card-location"><MapPin :size="14"/>大阪・{{restaurant.area}}</span><span v-if="restaurant.exploration" class="discovery-label">新しい発見</span><div class="card-info"><span class="card-price">{{priceLabel(restaurant)}} / 人</span><h2>{{restaurant.name}}</h2><div class="card-tags"><span v-for="key in Object.keys(restaurant.attributes).slice(0,3)" :key="key">{{attributeLabels[key]||key}}</span></div><p>{{restaurant.recommendationText}}</p><button class="card-detail" aria-label="店舗の詳細を見る" @pointerdown.stop @pointerup.stop @click.stop="emit('detail')"><ArrowUpRight :size="23"/></button></div></article><div class="reason-box"><Sparkles :size="18"/><div><strong>あなたへのおすすめ理由</strong><p v-for="reason in restaurant.recommendationReasons" :key="reason">{{reason}}</p></div></div></template>
